#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:30 x >/dev/null || { echo "book failed"; fail=1; }
grep -q '^# room' "$t" && grep -q '^aoi.2026-01-05.09:00.10:30.x$' "$t" || { echo "booking not appended"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y >/dev/null 2>&1; [ $? = 1 ] || { echo "overlap should exit 1"; fail=1; }
rm -f "$t"; exit $fail

spec/free.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-05\t10:00\t11:00\tx\naoi\t2026-01-05\t15:00\t16:00\ty\nkaede\t2026-01-05\t09:00\t18:00\tz\n' > "$t"
[ "$(BOOKINGS=$t bash src/free.sh aoi 2026-01-05 | tr '\n' ' ')" = '09:00-10:00 11:00-15:00 16:00-18:00 ' ] || { echo "free intervals of a day with two bookings"; fail=1; }
[ "$(BOOKINGS=$t bash src/free.sh sakura 2026-01-05)" = '09:00-18:00' ] || { echo "a day without bookings"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/free.sh kaede 2026-01-05)" ] || { echo "a fully booked day should print nothing"; fail=1; }
out=$(bash src/free.sh aoi 2>/dev/null); rc=$?
[ -z "$out" ] && [ "$rc" = 2 ] || { echo "usage goes to stderr with exit 2"; fail=1; }
rm -f "$t"; exit $fail

